package com.cryptostrategy.platform.persistence.api;import com.cryptostrategy.platform.backtesting.api.port.out.*;import com.cryptostrategy.platform.persistence.internal.backtesting.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import javax.sql.DataSource;import java.util.Objects;public final class BacktestingPersistenceFactory{private final JdbcTemplate jdbc;private final TransactionTemplate tx;private final BacktestJsonMapper json=new BacktestJsonMapper();public BacktestingPersistenceFactory(DataSource source){Objects.requireNonNull(source);jdbc=new JdbcTemplate(source);tx=new TransactionTemplate(new DataSourceTransactionManager(source));}public BacktestResultStore createResultStore(){return new JdbcBacktestResultStore(jdbc,tx,json);}public BacktestResultReader createResultReader(){return new JdbcBacktestEvidenceReader(jdbc,json);}}
